-- Retire legacy automatic queue entries without erasing source work or history.
-- Version marker makes this data migration safe to repeat.
update freelance_hq_task_time_entries e set ended_at=now(),duration_seconds=greatest(0,floor(extract(epoch from now()-e.started_at)))::integer,stop_reason='admin_action' from freelance_hq_tasks t join freelance_hq_profiles u on u.id=t.assigned_to where e.task_id=t.id and e.ended_at is null and t.fallback_template_key like 'workflow:%' and t.fallback_template_key not like '%:tabplan-v2:%' and u.name in ('Maaz Ali','Junaid Mazhar');
update freelance_hq_tasks t set fallback_template_key='retired:'||fallback_template_key,assigned_to=case when status='done' then assigned_to else null end,updated_at=now() from freelance_hq_profiles u where u.id=t.assigned_to and u.name in ('Maaz Ali','Junaid Mazhar') and t.is_fallback and t.fallback_template_key like 'workflow:%' and t.fallback_template_key not like '%:tabplan-v2:%';
insert into freelance_hq_seo_workflow_items(project_id,module,item_key,title,sort_order,details)
select a.project_id,'guest_blogging','prospect_research','Research suitable guest blogging websites',0,'{"steps":["Find relevant real websites for this client’s topic and location","Record each website URL, audience and evidence of real traffic","Record contact route and submission requirements","Send shortlisted prospects to Hamza for approval before outreach or payment"]}'::jsonb from freelance_hq_seo_module_assignments a join freelance_hq_projects p on p.id=a.project_id where a.module='guest_blogging' and not p.archived on conflict(project_id,module,item_key) do nothing;
with classified as (select i.*,case when i.module='local_listing' and i.item_key='google_business_profile' then 'gbp' when i.module='recurring' and i.item_key in ('gsc_performance_review','indexing_review','ranking_review','pagespeed_cwv_review','schema_validation','sitemap_robots_review','technical_seo_audit','tool_indexation_review') then 'gsc' when i.module='full_website' and i.item_key in ('breadcrumb_schema','broken_links_404','canonical_redirects','core_web_vitals','global_schema','google_search_console','https_security','robots_txt','xml_sitemap','tool_404_redirects','tool_generated_url_control','tool_internal_linking','tool_js_indexability','tool_mobile_ux','tool_performance','tool_schema','tool_sitemap_architecture') then 'technical_seo' when i.module='recurring' and i.item_key in ('broken_link_scan','indexing_review','pagespeed_cwv_review','schema_validation','sitemap_robots_review','technical_seo_audit','tool_indexation_review','tool_internal_links_review') then 'technical_seo' when i.module='recurring' then 'recurring_general' else i.module end as owner_group from freelance_hq_seo_workflow_items i where i.item_key not like 'demo_%' and i.title !~* '\mdemo\M'),
candidates as (select i.*,a.assigned_to,row_number() over(partition by i.project_id,i.owner_group order by case when exists(select 1 from freelance_hq_tasks old where old.project_id=i.project_id and old.fallback_template_key like 'retired:workflow:%' and split_part(old.fallback_template_key,':',4)=i.id::text) then 1 else 0 end,i.sort_order,i.title) as n from classified i join freelance_hq_seo_module_assignments a on a.project_id=i.project_id and a.module=i.owner_group join freelance_hq_projects p on p.id=i.project_id where not p.archived and i.owner_group not in ('gsc','gbp') and (i.module<>'recurring' and i.status<>'done' or i.module='recurring' and (i.completed_at is null or case when i.details->>'cadence'='weekly' then i.completed_at<=now()-interval '7 days' else date_trunc('month',i.completed_at)<date_trunc('month',now()) end))),
chosen as (select *, 'workflow:'||module||':'||id||':tabplan-v2:'||to_char(now() at time zone 'Asia/Karachi','YYYY-MM-DD') as task_key from candidates where n=1)
insert into freelance_hq_tasks(id,project_id,title,notes,status,priority,assigned_to,checklist,is_fallback,fallback_template_key,why,expected_outcome)
select md5(project_id::text||':'||task_key)::uuid,project_id,(case owner_group when 'technical_seo' then 'Technical SEO' when 'full_website' then 'Full Website' when 'social_media' then 'Social Media' when 'local_listing' then 'Local Listing' when 'blog_onsite' then 'Blog Onsite' when 'web_2_0' then 'Web 2.0' when 'guest_blogging' then 'Guest Blogging' else 'Recurring SEO' end)||' — '||title,'Fresh assignment under the approved tab plan. Complete the real checklist and record evidence in the matching project tab.','todo','medium',assigned_to,
(select jsonb_agg(jsonb_build_object('id',md5(chosen.id::text||':'||n),'text',step,'done',false)) from jsonb_array_elements_text(case when jsonb_typeof(details->'steps')='array' and jsonb_array_length(details->'steps')>0 then details->'steps' else jsonb_build_array('Complete '||title||' and record verification evidence') end) with ordinality x(step,n)),true,task_key,'Assigned by tab owner; replaces the legacy queue.','Verified work saved in the corresponding SEO tab.' from chosen
where not exists(select 1 from freelance_hq_tasks t where t.project_id=chosen.project_id and t.status<>'done' and t.fallback_template_key like 'workflow:%:tabplan-v2:%' and split_part(t.fallback_template_key,':',3)=chosen.id::text)
on conflict(id) do nothing;
with candidates as (select pp.*,a.assigned_to,row_number() over(partition by pp.project_id order by case when exists(select 1 from freelance_hq_tasks old where old.project_id=pp.project_id and old.fallback_template_key like 'retired:workflow:website_pages:%' and split_part(old.fallback_template_key,':',4)=pp.id::text) then 1 else 0 end,pp.name) as n from freelance_hq_project_pages pp join freelance_hq_seo_module_assignments a on a.project_id=pp.project_id and a.module='website_pages' join freelance_hq_projects p on p.id=pp.project_id where not p.archived and pp.is_active and exists(select 1 from freelance_hq_page_audit_checks c where c.page_id=pp.id and c.period_month=to_char(now() at time zone 'Asia/Karachi','YYYY-MM') and c.status not in ('done','not_applicable'))),chosen as (select *,'workflow:website_pages:'||id||':tabplan-v2:'||to_char(now() at time zone 'Asia/Karachi','YYYY-MM-DD') as task_key from candidates where n=1)
insert into freelance_hq_tasks(id,project_id,title,notes,status,priority,assigned_to,checklist,is_fallback,fallback_template_key,why,expected_outcome)
select md5(project_id::text||':'||task_key)::uuid,project_id,'Website Pages — '||name,'Page URL: '||url||'. Complete remaining saved checks; completed checks carry forward.','todo','medium',assigned_to,(select jsonb_agg(jsonb_build_object('id','pageaudit:'||chosen.id||':'||c.period_month||':'||c.check_key,'text',initcap(replace(c.check_key,'_',' ')),'done',c.status in ('done','not_applicable')) order by c.check_key) from freelance_hq_page_audit_checks c where c.page_id=chosen.id and c.period_month=to_char(now() at time zone 'Asia/Karachi','YYYY-MM')),true,task_key,'Fresh Website Pages assignment under the approved tab plan.','Remaining page checks completed and verified.' from chosen
where not exists(select 1 from freelance_hq_tasks t where t.project_id=chosen.project_id and t.status<>'done' and t.fallback_template_key like 'workflow:website_pages:%:tabplan-v2:%') on conflict(id) do nothing;
